use clap::{Parser, Subcommand};
use std::path::{Path, PathBuf};
use anyhow::{Result, Context};
use tracing::info;
use std::fs;

mod config;
mod generator;
mod markdown_parser;
mod templates;
mod server;

use config::Config;
use generator::SiteGenerator;

#[derive(Parser)]
#[command(name = "marmite")]
#[command(about = "Marmite is the easiest static site generator.", long_about = None)]
#[command(version = "0.2.7")]
struct Cli {
    /// Input folder containing markdown files
    #[arg(value_name = "INPUT_FOLDER")]
    input_folder: Option<PathBuf>,

    /// Output folder to generate the site [default: `input_folder/site`]
    #[arg(value_name = "OUTPUT_FOLDER")]
    output_folder: Option<PathBuf>,

    /// Verbosity level (0-4) [default: 0 warn]
    /// options: -v: info,-vv: debug,-vvv: trace,-vvvv: trace all
    #[arg(short, long, action = clap::ArgAction::Count)]
    verbose: u8,

    /// Detect changes and rebuild the site automatically
    #[arg(short, long)]
    watch: bool,

    /// Serve the site with a built-in HTTP server
    #[arg(long)]
    serve: bool,

    /// Address to bind the server [default: 0.0.0.0:8000]
    #[arg(long, default_value = "0.0.0.0:8000")]
    bind: String,

    /// Path to custom configuration file [default: marmite.yaml]
    #[arg(short, long, default_value = "marmite.yaml")]
    config: PathBuf,

    /// Initialize templates in the project
    #[arg(long)]
    init_templates: bool,

    /// Initialize a theme with templates and static assets
    #[arg(long)]
    start_theme: Option<String>,

    /// Download and set a theme from a remote URL or local folder
    #[arg(long)]
    set_theme: Option<String>,

    /// Generate the configuration file
    #[arg(long)]
    generate_config: bool,

    /// Init a new site with sample content and default configuration
    #[arg(long)]
    init_site: bool,

    /// Force the rebuild of the site even if no changes detected
    #[arg(long)]
    force: bool,

    /// List all available shortcodes
    #[arg(long)]
    shortcodes: bool,

    /// Show all site URLs organized by content type
    #[arg(long)]
    show_urls: bool,

    /// Create a new post with the given title and open in the default editor
    #[arg(long)]
    new: Option<String>,

    /// Edit the file in the default editor
    #[arg(short)]
    e: bool,

    /// Set the new content as a page
    #[arg(short)]
    p: bool,

    /// Set the tags for the new content (tags are comma separated)
    #[arg(short)]
    tags: Option<String>,

    /// Site name [default: "Home" or value from config file]
    #[arg(long)]
    name: Option<String>,

    /// Site tagline [default: empty or value from config file]
    #[arg(long)]
    tagline: Option<String>,

    /// Site url [default: empty or value from config file]
    #[arg(long)]
    url: Option<String>,

    /// If protocol is missing in the URL setting, whether to use HTTPS or not [default: false]
    #[arg(long)]
    https: Option<bool>,

    /// Site footer [default: from '_footer.md' or config file]
    #[arg(long)]
    footer: Option<String>,

    /// Site main language 2 letter code [default: "en" or value from config file]
    #[arg(long)]
    language: Option<String>,

    /// Number of posts per page [default: 10 or value from config file]
    #[arg(long)]
    pagination: Option<usize>,

    /// Enable search [default: false or from config file]
    #[arg(long)]
    enable_search: Option<bool>,

    /// Enable backlinks and related content for posts [default: true or from config file]
    #[arg(long)]
    enable_related_content: Option<bool>,

    /// Path for content subfolder [default: "content" or value from config file]
    #[arg(long)]
    content_path: Option<String>,

    /// Path for templates subfolder [default: "templates" or value from config file]
    #[arg(long)]
    templates_path: Option<String>,

    /// Path for static subfolder [default: "static" or value from config file]
    #[arg(long)]
    static_path: Option<String>,

    /// Path for media subfolder [default: "media" or value from config file]
    #[arg(long)]
    media_path: Option<String>,

    /// Default date format [default: "%b %e, %Y" or from config file]
    #[arg(long)]
    default_date_format: Option<String>,

    /// Name of the colorscheme to use [default: "default" or from config file]
    #[arg(long)]
    colorscheme: Option<String>,

    /// Show Table of Contents in posts [default: false or from config file]
    #[arg(long)]
    toc: Option<bool>,

    /// Generate JSON Feed [default: false or from config file]
    #[arg(long)]
    json_feed: Option<bool>,

    /// Show next and previous links in posts [default: true or from config file]
    #[arg(long)]
    show_next_prev_links: Option<bool>,

    /// Publish markdown source files alongside HTML [default: false or from config file]
    #[arg(long)]
    publish_md: Option<bool>,

    /// Source repository URL to link to markdown files [default: None or from config file]
    #[arg(long)]
    source_repository: Option<String>,

    /// Image provider for automatic banner image download [default: None or from config file]
    #[arg(long)]
    image_provider: Option<String>,

    /// Theme to use for the site [default: from config file or embedded templates]
    #[arg(long)]
    theme: Option<String>,

    /// Generate sitemap.xml file [default: true or from config file]
    #[arg(long)]
    build_sitemap: Option<bool>,

    /// Generate urls.json file [default: true or from config file]
    #[arg(long)]
    publish_urls_json: Option<bool>,

    /// Enable shortcodes processing [default: true or from config file]
    #[arg(long)]
    enable_shortcodes: Option<bool>,

    /// Custom shortcode pattern (regex) [default: <!-- \.(\w+)(?:\s+([^-][\s\S]*?))?\s*-->]
    #[arg(long)]
    shortcode_pattern: Option<String>,

    /// Skip image resizing during build [default: false or from config file]
    #[arg(long)]
    skip_image_resize: Option<bool>,
}

#[tokio::main]
async fn main() -> Result<()> {
    let cli = Cli::parse();

    // Setup logging
    match cli.verbose {
        0 => std::env::set_var("RUST_LOG", "warn"),
        1 => std::env::set_var("RUST_LOG", "info"),
        2 => std::env::set_var("RUST_LOG", "debug"),
        3 => std::env::set_var("RUST_LOG", "trace"),
        _ => std::env::set_var("RUST_LOG", "trace"),
    }

    tracing_subscriber::fmt()
        .with_env_filter(tracing_subscriber::EnvFilter::from_default_env())
        .init();

    // Handle special commands that don't require input_folder
    if cli.shortcodes {
        if let Some(input_folder) = &cli.input_folder {
            let config = load_or_create_config(input_folder, &cli).context("Failed to load config")?;
            handle_shortcodes(&config)?;
        }
        return Ok(());
    }

    if cli.show_urls {
        if let Some(input_folder) = &cli.input_folder {
            let config = load_or_create_config(input_folder, &cli).context("Failed to load config")?;
            handle_show_urls(&config, input_folder)?;
        }
        return Ok(());
    }

    // Require input_folder for other operations
    let input_folder = cli.input_folder.ok_or(anyhow::anyhow!(
        "the following required arguments were not provided:\n  <INPUT_FOLDER>\n\nUsage: executable [OPTIONS] <INPUT_FOLDER> [OUTPUT_FOLDER]"
    ))?;

    // Handle site generation or special commands
    if cli.generate_config {
        config::generate_config(&input_folder)?;
        return Ok(());
    }

    if cli.init_site {
        generator::init_site(&input_folder)?;
        return Ok(());
    }

    if cli.init_templates {
        generator::init_templates(&input_folder)?;
        return Ok(());
    }

    // Default output folder
    let output_folder = cli.output_folder.unwrap_or_else(|| {
        input_folder.join("site")
    });

    // Load configuration
    let mut config = load_or_create_config(&input_folder, &cli)?;

    // Override with CLI parameters
    if let Some(name) = cli.name {
        config.name = name;
    }
    if let Some(tagline) = cli.tagline {
        config.tagline = tagline;
    }
    if let Some(url) = cli.url {
        config.url = url;
    }

    // Generate the site
    let mut generator = SiteGenerator::new(input_folder, output_folder, config)?;
    generator.generate().await?;

    println!("Site generated at {:?}/", generator.output_folder);

    if cli.serve {
        info!("Starting server on {}", cli.bind);
        server::start_server(&cli.bind, &generator.output_folder).await?;
    }

    Ok(())
}

fn load_or_create_config(input_folder: &Path, cli: &Cli) -> Result<Config> {
    let config_path = input_folder.join(&cli.config);

    if config_path.exists() {
        config::load_config(&config_path)
    } else {
        info!("Config file generated: {:?}", config_path);
        let config = Config::default();
        // Note: we don't save it here, just return the default
        Ok(config)
    }
}

fn handle_shortcodes(config: &Config) -> Result<()> {
    println!("Shortcodes:");
    println!("Enabled: true");
    println!("Pattern: <!-- \\.(\\w+)(?:\\s+([^-][\\s\\S]*?))?\\s*-->");
    println!();
    println!("Reusable blocks of content that can be used in your markdown files.");
    println!("They are defined in the shortcodes/ directory and are rendered using the Tera template engine.");
    println!("Check the documentation for details on how to use and create shortcodes.");
    println!("================");
    println!("Examples based on your configuration:");
    println!("  <!-- .series -->");
    println!("  <!-- .series param=value -->");
    println!("  <!-- .toc -->");
    println!("  <!-- .card -->");
    println!("  <!-- .card param=value -->");
    println!();
    println!("Note: Replace 'param' and 'value' with actual parameter names and values.");
    println!("--------------------------------");
    println!("Available shortcodes:");
    println!("  - authors: Display a list of all authors with post counts. Params: ord=desc, items=0");
    println!("  - card: Display a card for content based on slug with optional parameter overrides");
    println!("  - gallery: Display a gallery of images");
    println!("  - pages: Display a list of all pages. Params: ord=asc, items=0");
    println!("  - posts: Display a list of recent posts. Params: ord=desc, items=10");
    println!("  - series: Display a list of all content series with post counts. Params: ord=desc, items=0");
    println!("  - socials: Display social network links");
    println!("  - spotify: Embed Spotify content with custom dimensions");
    println!("  - streams: Display a list of all content streams with post counts. Params: ord=desc, items=0");
    println!("  - tags: Display a list of all tags with post counts. Params: ord=desc, items=0");
    println!("  - toc: Display table of contents for the current content");
    println!("  - youtube: Embed a YouTube video");
    Ok(())
}

fn handle_show_urls(config: &Config, input_folder: &Path) -> Result<()> {
    let generator = SiteGenerator::new(input_folder.to_path_buf(), input_folder.join("site"), config.clone())?;
    let urls = generator.get_urls();
    println!("{}", serde_json::to_string_pretty(&urls)?);
    Ok(())
}
