use anyhow::Result;
use chrono::NaiveDate;
use serde::{Deserialize, Serialize};
use std::path::Path;

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ContentMetadata {
    pub title: String,
    pub date: Option<NaiveDate>,
    pub author: Option<String>,
    pub tags: Vec<String>,
    pub series: Option<String>,
    pub stream: Option<String>,
    pub slug: String,
    pub description: Option<String>,
}

#[derive(Debug, Clone)]
pub struct ParsedContent {
    pub metadata: ContentMetadata,
    pub html: String,
    pub raw: String,
}

pub fn parse_markdown_file(path: &Path) -> Result<ParsedContent> {
    let content = std::fs::read_to_string(path)?;
    parse_markdown(&content, path)
}

pub fn parse_markdown(content: &str, path: &Path) -> Result<ParsedContent> {
    let (metadata, markdown_content) = extract_frontmatter(content);

    // Parse markdown to HTML
    let parser = pulldown_cmark::Parser::new(&markdown_content);
    let mut html = String::new();
    pulldown_cmark::html::push_html(&mut html, parser);

    let filename = path.file_stem()
        .and_then(|s| s.to_str())
        .unwrap_or("untitled")
        .to_string();

    Ok(ParsedContent {
        metadata: ContentMetadata {
            title: metadata.get("title").cloned().unwrap_or_else(|| filename.clone()),
            date: metadata.get("date").and_then(|d| NaiveDate::parse_from_str(d, "%Y-%m-%d").ok()),
            author: metadata.get("author").cloned(),
            tags: metadata.get("tags")
                .map(|t| t.split(',').map(|s| s.trim().to_string()).collect())
                .unwrap_or_default(),
            series: metadata.get("series").cloned(),
            stream: metadata.get("stream").cloned(),
            slug: filename,
            description: metadata.get("description").cloned(),
        },
        html,
        raw: content.to_string(),
    })
}

fn extract_frontmatter(content: &str) -> (std::collections::HashMap<String, String>, String) {
    let mut metadata = std::collections::HashMap::new();
    let mut lines = content.lines().peekable();
    let mut markdown_content = String::new();

    // Check for YAML frontmatter
    if lines.peek() == Some(&"---") {
        lines.next(); // skip opening ---

        while let Some(line) = lines.peek() {
            if *line == "---" {
                lines.next(); // skip closing ---
                break;
            }

            if let Some((key, value)) = parse_metadata_line(lines.next().unwrap()) {
                metadata.insert(key, value);
            }
        }
    }

    // Collect remaining content
    for line in lines {
        markdown_content.push_str(line);
        markdown_content.push('\n');
    }

    // If no metadata was found, look for title in first heading
    if metadata.is_empty() {
        for line in content.lines() {
            if line.starts_with("# ") {
                metadata.insert("title".to_string(), line[2..].to_string());
                break;
            }
        }
        markdown_content = content.to_string();
    }

    (metadata, markdown_content)
}

fn parse_metadata_line(line: &str) -> Option<(String, String)> {
    let parts: Vec<&str> = line.splitn(2, ':').collect();
    if parts.len() == 2 {
        let key = parts[0].trim().to_string();
        let value = parts[1].trim().to_string();
        Some((key, value))
    } else {
        None
    }
}
