use walkdir::WalkDir;

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct SiteData {
    pub posts: Vec<ContentItem>,
    pub pages: Vec<ContentItem>,
    pub tags: HashMap<String, Vec<ContentItem>>,
    pub authors: HashMap<String, Vec<ContentItem>>,
    pub series: HashMap<String, Vec<ContentItem>>,
    pub streams: HashMap<String, Vec<ContentItem>>,
    pub archives: HashMap<String, Vec<ContentItem>>,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
