    pub pagination: Vec<String>,
    pub file_mappings: Vec<String>,
    pub misc: Vec<String>,
    pub summary: UrlsSummary,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct UrlsSummary {
    pub posts: usize,
    pub pages: usize,
    pub tags: usize,
    pub authors: usize,
    pub series: usize,
    pub streams: usize,
    pub archives: usize,
    pub feeds: usize,
    pub pagination: usize,
    pub file_mappings: usize,
    pub misc: usize,
    pub total: usize,
    pub meta: serde_json::json!({"url": "", "absolute_urls": false}),
}

pub struct SiteGenerator {
    pub input_folder: PathBuf,
    pub output_folder: PathBuf,
    pub config: Config,
    pub template_engine: TemplateEngine,
    pub site_data: SiteData,
}

impl SiteGenerator {
    pub fn new(
        input_folder: PathBuf,
        output_folder: PathBuf,
        config: Config,
    ) -> Result<Self> {
        let template_engine = TemplateEngine::new()?;

        Ok(SiteGenerator {
            input_folder,
            output_folder,
            config,
            template_engine,
            site_data: SiteData {
                posts: vec![],
                pages: vec![],
                tags: HashMap::new(),
                authors: HashMap::new(),
                series: HashMap::new(),
                streams: HashMap::new(),
                archives: HashMap::new(),
            },
        })
    }

    pub async fn generate(&mut self) -> Result<()> {
        // Create output directory
        fs::create_dir_all(&self.output_folder)?;

        // Extract and copy embedded assets
        self.copy_embedded_assets()?;

        // Process markdown files
        self.process_markdown_files()?;

        // Generate HTML files
        self.generate_html_files()?;

        // Generate special pages
        self.generate_index_page()?;
        self.generate_tags_page()?;
        self.generate_authors_page()?;
        self.generate_archive_page()?;
        self.generate_pages_listing()?;
        self.generate_series_page()?;
        self.generate_streams_page()?;
        self.generate_404_page()?;

        // Generate robots.txt
        self.generate_robots_txt()?;

        // Generate sitemap.xml if enabled
        if self.config.build_sitemap {
            self.generate_sitemap()?;
        }

        // Generate urls.json if enabled
        if self.config.publish_urls_json {
            self.generate_urls_json()?;
        }

        // Generate marmite.json
        self.generate_marmite_json()?;

        Ok(())
    }

    fn process_markdown_files(&mut self) -> Result<()> {
        let content_path = self.input_folder.join(&self.config.content_path);

        if !content_path.exists() {
            fs::create_dir_all(&content_path)?;
            return Ok(());
        }

        for entry in WalkDir::new(&content_path)
            .into_iter()
            .filter_map(|e| e.ok())
            .filter(|e| e.path().extension().map_or(false, |ext| ext == "md"))
        {
            let path = entry.path();

            // Skip special files starting with underscore
            if path.file_name()
                .and_then(|n| n.to_str())
                .map_or(false, |n| n.starts_with("_"))
            {
                continue;
            }

            if let Ok(parsed) = parse_markdown_file(path) {
                let is_page = path.file_name()
                    .and_then(|n| n.to_str())
                    .map_or(false, |n| !n.contains("20"));

                let url = format!("/{}.html", parsed.metadata.slug);

                let item = ContentItem {
                    title: parsed.metadata.title.clone(),
                    slug: parsed.metadata.slug.clone(),
                    url: url.clone(),
                    date: parsed.metadata.date.map(|d| d.to_string()),
                    author: parsed.metadata.author.clone(),
                    tags: parsed.metadata.tags.clone(),
                    series: parsed.metadata.series.clone(),
                    stream: parsed.metadata.stream.clone(),
                    description: parsed.metadata.description.clone(),
                    html: parsed.html.clone(),
                };

                if is_page {
                    self.site_data.pages.push(item.clone());
                } else {
                    self.site_data.posts.push(item.clone());
                }

                // Index by tags
                for tag in &parsed.metadata.tags {
                    self.site_data.tags.entry(tag.clone())
                        .or_insert_with(Vec::new)
                        .push(item.clone());
                }

                // Index by author
                if let Some(author) = &parsed.metadata.author {
                    self.site_data.authors.entry(author.clone())
                        .or_insert_with(Vec::new)
                        .push(item.clone());
                }

                // Index by series
                if let Some(series) = &parsed.metadata.series {
                    self.site_data.series.entry(series.clone())
                        .or_insert_with(Vec::new)
                        .push(item.clone());
                }

                // Index by stream
                if let Some(stream) = &parsed.metadata.stream {
                    self.site_data.streams.entry(stream.clone())
                        .or_insert_with(Vec::new)
                        .push(item.clone());
                }

                // Index by year for archives
                if let Some(date) = &parsed.metadata.date {
                    let year = date.year().to_string();
                    self.site_data.archives.entry(year)
                        .or_insert_with(Vec::new)
                        .push(item.clone());
                }
            }
        }

        Ok(())
    }

    fn generate_html_files(&self) -> Result<()> {
        for item in &self.site_data.pages {
            self.generate_content_page(item)?;
        }
        for item in &self.site_data.posts {
            self.generate_content_page(item)?;
        }
        Ok(())
    }

    fn generate_content_page(&self, item: &ContentItem) -> Result<()> {
        let page_path = self.output_folder.join(item.slug.trim_start_matches('/'));
        let html = self.template_engine.render_content(item, &self.config)?;
        fs::write(page_path, html)?;
        Ok(())
    }

    fn generate_index_page(&self) -> Result<()> {
        let mut posts = self.site_data.posts.clone();
        posts.sort_by(|a, b| {
            let a_date = a.date.as_ref().map(|d| d.as_str()).unwrap_or("");
            let b_date = b.date.as_ref().map(|d| d.as_str()).unwrap_or("");
            b_date.cmp(a_date)
        });

        let html = self.template_engine.render_index(&posts, &self.config)?;
        fs::write(self.output_folder.join("index.html"), html)?;
        Ok(())
    }

    fn generate_tags_page(&self) -> Result<()> {
        let html = self.template_engine.render_tags(&self.site_data.tags, &self.config)?;
        fs::write(self.output_folder.join("tags.html"), html)?;
        Ok(())
    }

    fn generate_authors_page(&self) -> Result<()> {
        let html = self.template_engine.render_authors(&self.site_data.authors, &self.config)?;
        fs::write(self.output_folder.join("authors.html"), html)?;
        Ok(())
    }

    fn generate_archive_page(&self) -> Result<()> {
        let html = self.template_engine.render_archive(&self.site_data.archives, &self.config)?;
        fs::write(self.output_folder.join("archive.html"), html)?;
        Ok(())
    }

    fn generate_pages_listing(&self) -> Result<()> {
        let html = self.template_engine.render_pages_listing(&self.site_data.pages, &self.config)?;
        fs::write(self.output_folder.join("pages.html"), html)?;
        Ok(())
    }

    fn generate_series_page(&self) -> Result<()> {
        let html = self.template_engine.render_series(&self.site_data.series, &self.config)?;
        fs::write(self.output_folder.join("series.html"), html)?;
        Ok(())
    }

    fn generate_streams_page(&self) -> Result<()> {
        let html = self.template_engine.render_streams(&self.site_data.streams, &self.config)?;
        fs::write(self.output_folder.join("streams.html"), html)?;
        Ok(())
    }

    fn generate_404_page(&self) -> Result<()> {
        let html = self.template_engine.render_404(&self.config)?;
        fs::write(self.output_folder.join("404.html"), html)?;
        Ok(())
    }

    fn generate_robots_txt(&self) -> Result<()> {
        let robots = "User-agent: *\nDisallow: \n";
        fs::write(self.output_folder.join("robots.txt"), robots)?;
        Ok(())
    }

    fn generate_sitemap(&self) -> Result<()> {
        let mut sitemap = String::from("<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<urlset xmlns=\"http://www.sitemaps.org/schemas/sitemap/0.9\">\n");

        for item in &self.site_data.posts {
            sitemap.push_str(&format!("  <url><loc>{}</loc></url>\n", item.url));
        }
        for item in &self.site_data.pages {
            sitemap.push_str(&format!("  <url><loc>{}</loc></url>\n", item.url));
        }

        sitemap.push_str("</urlset>");
        fs::write(self.output_folder.join("sitemap.xml"), sitemap)?;
        Ok(())
    }

    fn generate_urls_json(&self) -> Result<()> {
        let urls = self.get_urls();
        let json = serde_json::to_string_pretty(&urls)?;
        fs::write(self.output_folder.join("urls.json"), json)?;
        Ok(())
    }

    fn generate_marmite_json(&self) -> Result<()> {
        let meta = serde_json::json!({
            "generator": "marmite",
            "version": "0.2.7",
            "generated_at": Local::now().to_rfc3339(),
            "site_name": self.config.name,
            "content_count": {
                "posts": self.site_data.posts.len(),
                "pages": self.site_data.pages.len(),
            }
        });
        fs::write(self.output_folder.join("marmite.json"), meta.to_string())?;
        Ok(())
    }

    fn copy_embedded_assets(&self) -> Result<()> {
        let static_dir = self.output_folder.join("static");
        fs::create_dir_all(&static_dir)?;

        // Create placeholder assets - in a real implementation these would be embedded
        self.create_placeholder_assets(&static_dir)?;

        Ok(())
    }

    fn create_placeholder_assets(&self, static_dir: &Path) -> Result<()> {
        // Create CSS directory
        fs::create_dir_all(static_dir.join("colorschemes"))?;

        // Create placeholder CSS files
        let colorschemes = vec![
            "catppuccin", "clean", "dracula", "github", "gruvbox", "iceberg",
            "minimal", "minimal_wb", "monokai", "nord", "one", "solarized", "typewriter"
        ];

        for scheme in colorschemes {
            fs::write(static_dir.join(format!("colorschemes/{}.css", scheme)), "")?;
        }

        // Create main CSS
        fs::write(static_dir.join("marmite.css"), include_str!("../assets/marmite.css"))?;
        fs::write(static_dir.join("pico.min.css"), include_str!("../assets/pico.min.css"))?;
        fs::write(static_dir.join("custom.css"), "")?;
        fs::write(static_dir.join("custom.js"), "")?;
        fs::write(static_dir.join("marmite.js"), "")?;
        fs::write(static_dir.join("search.js"), "")?;
        fs::write(static_dir.join("robots.txt"), "User-agent: *\nDisallow: \n")?;

        // Create placeholder favicon and images
        fs::write(static_dir.join("favicon.ico"), b"")?;
        fs::write(static_dir.join("logo.png"), b"")?;
        fs::write(static_dir.join("avatar-placeholder.png"), b"")?;

        // Create font placeholder
        fs::write(static_dir.join("Atkinson-Hyperlegible-Regular-102.woff"), b"")?;

        Ok(())
    }

    pub fn get_urls(&self) -> UrlsOutput {
        let mut posts = vec![];
        let mut pages = vec![];
        let mut tags = vec![];
        let mut authors = vec![];
        let mut series = vec![];
        let mut streams = vec![];
        let mut archives = vec![];
        let mut pagination = vec!["/pages-1.html".to_string()];
        let mut misc = vec!["/index.html".to_string()];

        for post in &self.site_data.posts {
            posts.push(post.url.clone());
        }
        for page in &self.site_data.pages {
            pages.push(page.url.clone());
        }
        for tag in self.site_data.tags.keys() {
            tags.push(format!("/tags/{}.html", tag));
        }
        for author in self.site_data.authors.keys() {
            authors.push(format!("/authors/{}.html", author));
        }
        for series in self.site_data.series.keys() {
            series.push(format!("/series/{}.html", series));
        }
        for stream in self.site_data.streams.keys() {
            streams.push(format!("/streams/{}.html", stream));
        }
        for year in self.site_data.archives.keys() {
            archives.push(format!("/archive/{}.html", year));
        }

        let total = posts.len() + pages.len() + tags.len() + authors.len() 
            + series.len() + streams.len() + archives.len() + pagination.len() + misc.len();

        UrlsOutput {
            posts,
            pages,
            tags,
            authors,
            series,
            streams,
            archives,
            feeds: vec![],
            pagination,
            file_mappings: vec![],
            misc,
            summary: UrlsSummary {
                posts: self.site_data.posts.len(),
                pages: self.site_data.pages.len(),
                tags: self.site_data.tags.len(),
                authors: self.site_data.authors.len(),
                series: self.site_data.series.len(),
                streams: self.site_data.streams.len(),
                archives: self.site_data.archives.len(),
                feeds: 0,
                pagination: pagination.len(),
                file_mappings: 0,
                misc: misc.len(),
                total,
                meta: serde_json::json!({"url": "", "absolute_urls": false}),
            },
        }
    }
}

pub fn init_site(input_folder: &Path) -> Result<()> {
    // Create config
    crate::config::generate_config(input_folder)?;

    // Create directories
    let content_dir = input_folder.join("content");
    fs::create_dir_all(&content_dir)?;

    // Create sample markdown files
    let today = Local::now().format("%Y-%m-%d").to_string();
    fs::write(
