            "minimal", "minimal_wb", "monokai", "nord", "one", "solarized", "typewriter"
        ];

        for scheme in colorschemes {
            fs::write(static_dir.join(format!("colorschemes/{}.css", scheme)), "")?;
        }

        // Create main CSS
        fs::write(static_dir.join("marmite.css"), include_str!("../assets/marmite.css"))?;
        fs::write(static_dir.join("pico.min.css"), include_str!("../assets/pico.min.css"))?;
