        // Create placeholder favicon and images
        fs::write(static_dir.join("favicon.ico"), b"")?;
        fs::write(static_dir.join("logo.png"), b"")?;
        fs::write(static_dir.join("avatar-placeholder.png"), b"")?;

        // Create font placeholder
        fs::write(static_dir.join("Atkinson-Hyperlegible-Regular-102.woff"), b"")?;

        Ok(())
    }

    pub fn get_urls(&self) -> UrlsOutput {
        let mut posts = vec![];
        let mut pages = vec![];
        let mut tags = vec![];
        let mut authors = vec![];
        let mut series = vec![];
        let mut streams = vec![];
        let mut archives = vec![];
        let mut pagination = vec!["/pages-1.html".to_string()];
        let mut misc = vec!["/index.html".to_string()];

        for post in &self.site_data.posts {
            posts.push(post.url.clone());
        }
        for page in &self.site_data.pages {
            pages.push(page.url.clone());
        }
        for tag in self.site_data.tags.keys() {
            tags.push(format!("/tags/{}.html", tag));
        }
        for author in self.site_data.authors.keys() {
            authors.push(format!("/authors/{}.html", author));
        }
        for series in self.site_data.series.keys() {
            series.push(format!("/series/{}.html", series));
        }
        for stream in self.site_data.streams.keys() {
            streams.push(format!("/streams/{}.html", stream));
        }
        for year in self.site_data.archives.keys() {
            archives.push(format!("/archive/{}.html", year));
        }

        let total = posts.len() + pages.len() + tags.len() + authors.len() 
            + series.len() + streams.len() + archives.len() + pagination.len() + misc.len();

        UrlsOutput {
            posts,
            pages,
            tags,
            authors,
            series,
            streams,
            archives,
            feeds: vec![],
            pagination,
            file_mappings: vec![],
            misc,
            summary: UrlsSummary {
                posts: self.site_data.posts.len(),
                pages: self.site_data.pages.len(),
                tags: self.site_data.tags.len(),
                authors: self.site_data.authors.len(),
                series: self.site_data.series.len(),
                streams: self.site_data.streams.len(),
                archives: self.site_data.archives.len(),
                feeds: 0,
                pagination: pagination.len(),
                file_mappings: 0,
                misc: misc.len(),
                total,
                meta: serde_json::json!({"url": "", "absolute_urls": false}),
            },
        }
    }
}

pub fn init_site(input_folder: &Path) -> Result<()> {
    // Create config
    crate::config::generate_config(input_folder)?;

    // Create directories
    let content_dir = input_folder.join("content");
    fs::create_dir_all(&content_dir)?;

    // Create sample markdown files
    let today = Local::now().format("%Y-%m-%d").to_string();
    fs::write(
        content_dir.join(format!("{}-welcome.md", today)),
        include_str!("../templates/welcome.md"),
    )?;

    fs::write(content_dir.join("about.md"), "# About\n\nWelcome to your site!")?;
    fs::write(content_dir.join("_404.md"), "# 404 Not Found")?;

    tracing::info!("Site initialized in {:?}", input_folder);
    Ok(())
}

pub fn init_templates(input_folder: &Path) -> Result<()> {
    let templates_dir = input_folder.join("templates");
    fs::create_dir_all(&templates_dir)?;

    // Create basic template files
    fs::write(templates_dir.join("base.html"), include_str!("../templates/base.html"))?;

    tracing::info!("Templates initialized in {:?}", templates_dir);
    Ok(())
