    fs::write(content_dir.join("_404.md"), "# 404 Not Found")?;

    tracing::info!("Site initialized in {:?}", input_folder);
    Ok(())
}

pub fn init_templates(input_folder: &Path) -> Result<()> {
    let templates_dir = input_folder.join("templates");
    fs::create_dir_all(&templates_dir)?;

    // Create basic template files
    fs::write(templates_dir.join("base.html"), include_str!("../templates/base.html"))?;

