use actix_web::{web, App, HttpServer};
use actix_files as fs;
use anyhow::Result;
use std::path::Path;

pub async fn start_server(bind: &str, static_dir: &Path) -> Result<()> {
    let static_dir_str = static_dir.to_string_lossy().to_string();

    HttpServer::new(move || {
        App::new().service(
            fs::Files::new("/", static_dir_str.clone())
                .index_file("index.html")
        )
    })
    .bind(bind)?
    .run()
    .await?;

    Ok(())
}
