{% extends "base.html" %}

{% block meta %}
<meta property="og:title" content="{{ item.title }}">
<meta property="og:description" content="{{ item.description | default(value='') }}">
<meta property="og:type" content="article">
<meta property="og:site_name" content="{{ config.name }}">

<script type="application/ld+json">
{
    "@context": "https://schema.org",
    "@type": "BlogPosting",
    "mainEntityOfPage": {
        "@type": "WebPage",
        "@id": "{{ item.url }}"
    },
    "url": "{{ item.url }}",
    "headline": "{{ item.title }}",
    "description": "{{ item.description | default(value='') }}",
    "datePublished": "{{ item.date | default(value='') }}",
    "author": {
        "@type": "Person",
        "name": "{{ item.author | default(value=config.default_author) }}"
    }
}
</script>
{% endblock %}

{% block title %}{{ item.title }} - {{ config.name }}{% endblock %}

{% block content %}
<article>
    <h1>{{ item.title }}</h1>
    {% if item.date %}
        <p><small>Published on {{ item.date }}</small></p>
    {% endif %}
    {% if item.author %}
        <p><small>By {{ item.author }}</small></p>
    {% endif %}
    {% if item.tags %}
        <p>
            {% for tag in item.tags %}
                <a href="/tags/{{ tag }}.html">#{{ tag }}</a>
            {% endfor %}
        </p>
    {% endif %}
    <div class="content">
        {{ item.html | safe }}
    </div>
</article>
{% endblock %}
EOF

