        if let Err(e) = generator::init_site(input_path) {
            eprintln!("Error initializing site: {}", e);
            process::exit(1);
        }
        return;
    }

    let output_folder = output_folder.unwrap_or_else(|| format!("{}/site", input_folder));
    let output_path = Path::new(&output_folder);

