use std::fs;
use std::path::Path;
use std::collections::HashMap;

#[derive(Debug, Clone)]
pub struct ContentMetadata {
    pub title: String,
    pub date: Option<String>,
    pub author: Option<String>,
    pub tags: Vec<String>,
    pub series: Option<String>,
    pub stream: Option<String>,
    pub slug: String,
    pub description: Option<String>,
}

#[derive(Debug, Clone)]
pub struct ParsedContent {
    pub metadata: ContentMetadata,
    pub html: String,
    pub raw: String,
}

pub fn parse_markdown_file(path: &Path) -> Result<ParsedContent, String> {
    let content = fs::read_to_string(path)
        .map_err(|e| format!("Failed to read file: {}", e))?;
    parse_markdown(&content, path)
}

pub fn parse_markdown(content: &str, path: &Path) -> Result<ParsedContent, String> {
    let (metadata, markdown_content) = extract_frontmatter(content);

    // Simple markdown to HTML conversion
    let html = simple_markdown_to_html(&markdown_content);

    let filename = path.file_stem()
        .and_then(|s| s.to_str())
        .unwrap_or("untitled")
        .to_string();

    Ok(ParsedContent {
        metadata: ContentMetadata {
            title: metadata.get("title").cloned().unwrap_or_else(|| filename.clone()),
            date: metadata.get("date").cloned(),
            author: metadata.get("author").cloned(),
            tags: metadata.get("tags")
                .map(|t| t.split(',').map(|s| s.trim().to_string()).collect())
                .unwrap_or_default(),
            series: metadata.get("series").cloned(),
            stream: metadata.get("stream").cloned(),
            slug: filename,
            description: metadata.get("description").cloned(),
        },
        html,
        raw: content.to_string(),
    })
}

fn extract_frontmatter(content: &str) -> (HashMap<String, String>, String) {
    let mut metadata = HashMap::new();
    let mut lines = content.lines().peekable();
    let mut markdown_content = String::new();
    let mut in_frontmatter = false;

    // Check for YAML frontmatter
    if lines.peek() == Some(&"---") {
        in_frontmatter = true;
        lines.next(); // skip opening ---

        while let Some(line) = lines.next() {
            if line == "---" {
