        raw: content.to_string(),
    })
}

fn extract_frontmatter(content: &str) -> (HashMap<String, String>, String) {
    let mut metadata = HashMap::new();
    let mut lines = content.lines().peekable();
    let mut markdown_content = String::new();
    let mut in_frontmatter = false;

    // Check for YAML frontmatter
    if lines.peek() == Some(&"---") {
        in_frontmatter = true;
        lines.next(); // skip opening ---

        while let Some(line) = lines.next() {
            if line == "---" {
                in_frontmatter = false;
                break;
            }

            if let Some((key, value)) = parse_metadata_line(line) {
                metadata.insert(key, value);
            }
        }
    }

    // Collect remaining content
    if in_frontmatter {
        // If frontmatter wasn't closed properly, treat everything as markdown
        markdown_content = content.to_string();
    } else {
        for line in lines {
            markdown_content.push_str(line);
            markdown_content.push('\n');
        }
    }

    // If no metadata was found, look for title in first heading
    if metadata.is_empty() && markdown_content.is_empty() {
        for line in content.lines() {
            if line.starts_with("# ") {
                metadata.insert("title".to_string(), line[2..].to_string());
                break;
            }
        }
        markdown_content = content.to_string();
    }

    (metadata, markdown_content)
}

fn parse_metadata_line(line: &str) -> Option<(String, String)> {
    let parts: Vec<&str> = line.splitn(2, ':').collect();
    if parts.len() == 2 {
        let key = parts[0].trim().to_string();
        let value = parts[1].trim().to_string();
        Some((key, value))
    } else {
        None
    }
}

fn simple_markdown_to_html(markdown: &str) -> String {
    let mut html = String::new();
    let mut in_list = false;
    let mut in_code_block = false;
    let mut code_block_content = String::new();

    for line in markdown.lines() {
        let trimmed = line.trim();

        // Code blocks
        if trimmed.starts_with("```") {
            if in_code_block {
                html.push_str("<code>");
                html.push_str(&escape_html(&code_block_content));
                html.push_str("</code>\n");
                code_block_content.clear();
                in_code_block = false;
            } else {
                in_code_block = true;
            }
            continue;
        }

        if in_code_block {
            code_block_content.push_str(line);
            code_block_content.push('\n');
            continue;
        }

        // Headers
        if trimmed.starts_with("# ") {
            html.push_str(&format!("<h1>{}</h1>\n", escape_html(&trimmed[2..])));
        } else if trimmed.starts_with("## ") {
            html.push_str(&format!("<h2>{}</h2>\n", escape_html(&trimmed[3..])));
        } else if trimmed.starts_with("### ") {
            html.push_str(&format!("<h3>{}</h3>\n", escape_html(&trimmed[4..])));
        } else if trimmed.starts_with("#### ") {
            html.push_str(&format!("<h4>{}</h4>\n", escape_html(&trimmed[5..])));
        } else if trimmed.starts_with("##### ") {
            html.push_str(&format!("<h5>{}</h5>\n", escape_html(&trimmed[6..])));
        } else if trimmed.starts_with("###### ") {
            html.push_str(&format!("<h6>{}</h6>\n", escape_html(&trimmed[7..])));
        }
        // Lists
        else if trimmed.starts_with("- ") {
            if !in_list {
                html.push_str("<ul>\n");
                in_list = true;
            }
            html.push_str(&format!("<li>{}</li>\n", escape_html(&trimmed[2..])));
        }
        // Paragraphs
        else if !trimmed.is_empty() {
            if in_list {
                html.push_str("</ul>\n");
                in_list = false;
            }
            let content = apply_inline_formatting(trimmed);
            html.push_str(&format!("<p>{}</p>\n", content));
        }
    }

    if in_list {
        html.push_str("</ul>\n");
    }

    html
}

fn apply_inline_formatting(text: &str) -> String {
    let mut result = String::new();
    let mut chars = text.chars().peekable();

    while let Some(ch) = chars.next() {
        if ch == '*' {
            // Check for bold or italic
            if chars.peek() == Some(&'*') {
                chars.next(); // consume second *
                let mut bold_content = String::new();
                let mut count = 0;
                let mut found_close = false;

                while let Some(c) = chars.next() {
                    if c == '*' && chars.peek() == Some(&'*') {
                        chars.next();
                        found_close = true;
                        break;
                    }
                    bold_content.push(c);
                }

                if found_close {
                    result.push_str(&format!("<strong>{}</strong>", escape_html(&bold_content)));
                } else {
                    result.push_str(&format!("**{}", bold_content));
                }
            } else {
                // Italic
                let mut italic_content = String::new();
                let mut found_close = false;

                while let Some(c) = chars.next() {
                    if c == '*' {
                        found_close = true;
                        break;
                    }
                    italic_content.push(c);
                }

                if found_close {
                    result.push_str(&format!("<em>{}</em>", escape_html(&italic_content)));
                } else {
                    result.push_str(&format!("*{}", italic_content));
                }
            }
        } else if ch == '[' {
            // Links
            let mut link_text = String::new();
            while let Some(c) = chars.next() {
                if c == ']' {
                    break;
                }
                link_text.push(c);
            }

            if chars.peek() == Some(&'(') {
                chars.next(); // consume (
                let mut url = String::new();
                while let Some(c) = chars.next() {
                    if c == ')' {
                        break;
                    }
                    url.push(c);
                }
                result.push_str(&format!("<a href=\"{}\">{}</a>", url, escape_html(&link_text)));
            } else {
                result.push_str(&format!("[{}]", link_text));
            }
        } else if ch == '`' {
            // Inline code
            let mut code = String::new();
            while let Some(c) = chars.next() {
                if c == '`' {
                    break;
                }
                code.push(c);
            }
            result.push_str(&format!("<code>{}</code>", escape_html(&code)));
        } else {
            result.push(ch);
        }
    }

    escape_html(&result)
}

fn escape_html(text: &str) -> String {
    text.replace("&", "&amp;")
        .replace("<", "&lt;")
        .replace(">", "&gt;")
        .replace("\"", "&quot;")
        .replace("'", "&#39;")
}
