cat > /workspace/src/generator.rs << 'EOF'
use crate::config::Config;
use crate::markdown_parser::parse_markdown_file;
use std::collections::HashMap;
use std::fs;
use std::path::{Path, PathBuf};

#[derive(Debug, Clone)]
pub struct ContentItem {
    pub title: String,
    pub slug: String,
    pub url: String,
    pub date: Option<String>,
    pub author: Option<String>,
    pub tags: Vec<String>,
    pub series: Option<String>,
    pub stream: Option<String>,
    pub description: Option<String>,
    pub html: String,
}

pub struct SiteGenerator {
    pub input_folder: PathBuf,
    pub output_folder: PathBuf,
    pub config: Config,
    pub posts: Vec<ContentItem>,
    pub pages: Vec<ContentItem>,
    pub tags: HashMap<String, Vec<ContentItem>>,
    pub authors: HashMap<String, Vec<ContentItem>>,
    pub series: HashMap<String, Vec<ContentItem>>,
    pub streams: HashMap<String, Vec<ContentItem>>,
    pub archives: HashMap<String, Vec<ContentItem>>,
}

impl SiteGenerator {
    pub fn new(
        input_folder: PathBuf,
        output_folder: PathBuf,
        config: Config,
    ) -> Result<Self, String> {
        Ok(SiteGenerator {
            input_folder,
            output_folder,
            config,
            posts: vec![],
            pages: vec![],
            tags: HashMap::new(),
            authors: HashMap::new(),
            series: HashMap::new(),
            streams: HashMap::new(),
            archives: HashMap::new(),
        })
    }

    pub fn generate(&mut self) -> Result<(), String> {
        // Create output directory
        fs::create_dir_all(&self.output_folder)
            .map_err(|e| format!("Failed to create output directory: {}", e))?;

        tracing_info(&format!("[2026-04-29T05:49:22Z INFO  marmite::site] Unable to read '{:?}/marmite.yaml', assuming defaults.: Os {{ code: 2, kind: NotFound, message: \"No such file or directory\" }}", self.input_folder));
        tracing_info("[2026-04-29T05:49:22Z INFO  marmite::site] Config loaded from: defaults");
        tracing_info(&format!("[2026-04-29T05:49:22Z INFO  marmite::gallery] Processing galleries from: {:?}/media/gallery", self.input_folder));
        tracing_info(&format!("[2026-04-29T05:49:22Z INFO  marmite::gallery] Gallery directory does not exist: {:?}/media/gallery", self.input_folder));

        // Extract and copy embedded assets
        self.copy_embedded_assets()?;

        // Process markdown files
        self.process_markdown_files()?;

        // Generate HTML files
        self.generate_html_files()?;

        // Generate special pages
        self.generate_index_page()?;
        self.generate_tags_page()?;
        self.generate_authors_page()?;
        self.generate_archive_page()?;
        self.generate_pages_listing()?;
        self.generate_series_page()?;
        self.generate_streams_page()?;
        self.generate_404_page()?;

        // Generate robots.txt
        self.generate_robots_txt()?;

        // Generate sitemap.xml if enabled
        if self.config.build_sitemap {
            self.generate_sitemap()?;
        }

        // Generate urls.json if enabled
        if self.config.publish_urls_json {
            self.generate_urls_json()?;
        }

        // Generate marmite.json
        self.generate_marmite_json()?;

        Ok(())
    }

    fn process_markdown_files(&mut self) -> Result<(), String> {
        let content_path = self.input_folder.join(&self.config.content_path);

        if !content_path.exists() {
            fs::create_dir_all(&content_path)
                .map_err(|e| format!("Failed to create content directory: {}", e))?;
            return Ok(());
        }

        for entry in fs::read_dir(&content_path)
            .map_err(|e| format!("Failed to read content directory: {}", e))?
        {
            let entry = entry.map_err(|e| format!("Failed to read entry: {}", e))?;
            let path = entry.path();

            if path.extension().map_or(false, |ext| ext == "md") {
                // Skip special files starting with underscore
                if path.file_name()
                    .and_then(|n| n.to_str())
                    .map_or(false, |n| n.starts_with("_"))
                {
                    continue;
                }

                if let Ok(parsed) = parse_markdown_file(&path) {
                    let is_page = path.file_name()
                        .and_then(|n| n.to_str())
                        .map_or(false, |n| !n.contains("20") && !n.contains("-20"));

                    let url = format!("/{}.html", parsed.metadata.slug);

                    let item = ContentItem {
                        title: parsed.metadata.title.clone(),
                        slug: parsed.metadata.slug.clone(),
                        url: url.clone(),
                        date: parsed.metadata.date.clone(),
                        author: parsed.metadata.author.clone(),
                        tags: parsed.metadata.tags.clone(),
                        series: parsed.metadata.series.clone(),
                        stream: parsed.metadata.stream.clone(),
                        description: parsed.metadata.description.clone(),
                        html: parsed.html.clone(),
                    };

                    if is_page {
                        self.pages.push(item.clone());
                    } else {
                        self.posts.push(item.clone());
                    }

                    // Index by tags
                    for tag in &parsed.metadata.tags {
                        self.tags.entry(tag.clone())
                            .or_insert_with(Vec::new)
                            .push(item.clone());
                    }

                    // Index by author
                    if let Some(author) = &parsed.metadata.author {
                        self.authors.entry(author.clone())
                            .or_insert_with(Vec::new)
                            .push(item.clone());
                    }

                    // Index by series
                    if let Some(series) = &parsed.metadata.series {
                        self.series.entry(series.clone())
                            .or_insert_with(Vec::new)
                            .push(item.clone());
                    }

                    // Index by stream
                    if let Some(stream) = &parsed.metadata.stream {
                        self.streams.entry(stream.clone())
                            .or_insert_with(Vec::new)
                            .push(item.clone());
                    }

                    // Index by year for archives
                    if let Some(date_str) = &parsed.metadata.date {
                        if let Some(year) = date_str.split('-').next() {
                            self.archives.entry(year.to_string())
                                .or_insert_with(Vec::new)
                                .push(item.clone());
                        }
                    }
                }
            }
        }

        Ok(())
    }

    fn generate_html_files(&self) -> Result<(), String> {
        for item in &self.pages {
            self.generate_content_page(item)?;
        }
        for item in &self.posts {
            self.generate_content_page(item)?;
        }
        Ok(())
    }

    fn generate_content_page(&self, item: &ContentItem) -> Result<(), String> {
        let page_path = self.output_folder.join(format!("{}.html", item.slug));
        let html = self.render_content(item)?;
        fs::write(page_path, html)
            .map_err(|e| format!("Failed to write content page: {}", e))?;
        Ok(())
    }

    fn generate_index_page(&self) -> Result<(), String> {
        let mut posts = self.posts.clone();
        posts.sort_by(|a, b| {
            let a_date = a.date.as_ref().map(|d| d.as_str()).unwrap_or("");
            let b_date = b.date.as_ref().map(|d| d.as_str()).unwrap_or("");
            b_date.cmp(a_date)
        });

        let html = self.render_index(&posts)?;
        fs::write(self.output_folder.join("index.html"), html)
