    pub fn get_urls_json(&self) -> String {
        let mut posts_urls = vec![];
        let mut pages_urls = vec![];
        let mut tags_urls = vec![];
        let mut authors_urls = vec![];
        let mut series_urls = vec![];
        let mut streams_urls = vec![];
        let mut archives_urls = vec![];
        let pagination = vec!["/pages-1.html".to_string()];
        let misc = vec!["/index.html".to_string()];

        for post in &self.posts {
            posts_urls.push(format!("\"{}\"", post.url));
        }
        for page in &self.pages {
            pages_urls.push(format!("\"{}\"", page.url));
        }
        for tag in self.tags.keys() {
            tags_urls.push(format!("\"/tags/{}.html\"", tag));
        }
        for author in self.authors.keys() {
            authors_urls.push(format!("\"/authors/{}.html\"", author));
        }
        for series in self.series.keys() {
            series_urls.push(format!("\"/series/{}.html\"", series));
        }
        for stream in self.streams.keys() {
            streams_urls.push(format!("\"/streams/{}.html\"", stream));
        }
        for year in self.archives.keys() {
            archives_urls.push(format!("\"/archive/{}.html\"", year));
        }

        let total = self.posts.len() + self.pages.len() + self.tags.len() + self.authors.len()
            + self.series.len() + self.streams.len() + self.archives.len() + pagination.len() + misc.len();

        format!(r#"{{
  "posts": [{}],
  "pages": [{}],
  "tags": [{}],
  "authors": [{}],
  "series": [{}],
  "streams": [{}],
  "archives": [{}],
  "feeds": [],
  "pagination": [{}],
  "file_mappings": [],
  "misc": [{}],
  "summary": {{
    "posts": {},
    "pages": {},
    "tags": {},
    "authors": {},
    "series": {},
    "streams": {},
    "archives": {},
    "feeds": 0,
    "pagination": {},
    "file_mappings": 0,
    "misc": {},
    "total": {},
    "meta": {{
      "url": "",
      "absolute_urls": false
    }}
  }}
}}"#,
            posts_urls.join(", "),
            pages_urls.join(", "),
            tags_urls.join(", "),
            authors_urls.join(", "),
            series_urls.join(", "),
            streams_urls.join(", "),
            archives_urls.join(", "),
            pagination.iter().map(|p| format!("\"{}\"", p)).collect::<Vec<_>>().join(", "),
            misc.iter().map(|p| format!("\"{}\"", p)).collect::<Vec<_>>().join(", "),
            self.posts.len(),
            self.pages.len(),
            self.tags.len(),
            self.authors.len(),
            self.series.len(),
            self.streams.len(),
            self.archives.len(),
            pagination.len(),
            misc.len(),
            total,
        )
    }

