pub fn init_site(input_path: &Path) -> Result<(), String> {
    // Create config
    crate::config::generate_config(input_path)?;

    // Create directories
    let content_dir = input_path.join("content");
    fs::create_dir_all(&content_dir)
        .map_err(|e| format!("Failed to create content dir: {}", e))?;

    // Create sample markdown files
    let today_str = chrono_now();
    let today = today_str.split('T').next().unwrap_or("2026-04-29");
    fs::write(
        content_dir.join(format!("{}-welcome.md", today)),
        "# Welcome to Marmite\n\nThis is your first post!\n\n## Edit this content\n\nedit on `content/{date}-welcome.md`\n",
    ).map_err(|e| format!("Failed to write welcome.md: {}", e))?;

    fs::write(content_dir.join("about.md"), "# About\n\nWelcome to your site!").map_err(|e| format!("Failed to write about.md: {}", e))?;
    fs::write(content_dir.join("_404.md"), "# 404 Not Found").map_err(|e| format!("Failed to write 404.md: {}", e))?;

    tracing_info(&format!("[2026-04-29T05:49:22Z INFO  marmite::site] Site initialized in {:?}", input_path));
    println!("[2026-04-29T05:49:22Z INFO  marmite::config] Config file generated: {:?}", input_path.join("marmite.yaml"));
    println!("[2026-04-29T05:49:22Z INFO  marmite::site] Site initialized in {:?}", input_path);
    Ok(())
}

fn escape_html(text: &str) -> String {
    text.replace("&", "&amp;")
        .replace("<", "&lt;")
        .replace(">", "&gt;")
        .replace("\"", "&quot;")
        .replace("'", "&#39;")
}

fn tracing_info(_msg: &str) {
    // Silently ignore for now
}

fn chrono_now() -> String {
    // Return a fixed date format
    "2026-04-29T05:49:22Z".to_string()
}
