            fs::create_dir_all(&content_path)
                .map_err(|e| format!("Failed to create content directory: {}", e))?;
            return Ok(());
        }

        for entry in fs::read_dir(&content_path)
            .map_err(|e| format!("Failed to read content directory: {}", e))?
        {
            let entry = entry.map_err(|e| format!("Failed to read entry: {}", e))?;
            let path = entry.path();

            if path.extension().map_or(false, |ext| ext == "md") {
                // Skip special files starting with underscore
                if path.file_name()
                    .and_then(|n| n.to_str())
                    .map_or(false, |n| n.starts_with("_"))
                {
                    continue;
                }

                if let Ok(parsed) = parse_markdown_file(&path) {
                    let is_page = path.file_name()
                        .and_then(|n| n.to_str())
                        .map_or(false, |n| !n.contains("20") && !n.contains("-20"));

                    let url = format!("/{}.html", parsed.metadata.slug);

                    let item = ContentItem {
                        title: parsed.metadata.title.clone(),
                        slug: parsed.metadata.slug.clone(),
                        url: url.clone(),
                        date: parsed.metadata.date.clone(),
                        author: parsed.metadata.author.clone(),
                        tags: parsed.metadata.tags.clone(),
                        series: parsed.metadata.series.clone(),
                        stream: parsed.metadata.stream.clone(),
                        description: parsed.metadata.description.clone(),
                        html: parsed.html.clone(),
                    };

                    if is_page {
                        self.pages.push(item.clone());
                    } else {
                        self.posts.push(item.clone());
                    }

                    // Index by tags
                    for tag in &parsed.metadata.tags {
                        self.tags.entry(tag.clone())
                            .or_insert_with(Vec::new)
                            .push(item.clone());
                    }

                    // Index by author
                    if let Some(author) = &parsed.metadata.author {
                        self.authors.entry(author.clone())
                            .or_insert_with(Vec::new)
                            .push(item.clone());
                    }

                    // Index by series
                    if let Some(series) = &parsed.metadata.series {
                        self.series.entry(series.clone())
                            .or_insert_with(Vec::new)
                            .push(item.clone());
                    }

                    // Index by stream
                    if let Some(stream) = &parsed.metadata.stream {
                        self.streams.entry(stream.clone())
                            .or_insert_with(Vec::new)
                            .push(item.clone());
                    }

                    // Index by year for archives
                    if let Some(date_str) = &parsed.metadata.date {
                        if let Some(year) = date_str.split('-').next() {
                            self.archives.entry(year.to_string())
                                .or_insert_with(Vec::new)
                                .push(item.clone());
                        }
                    }
                }
            }
        }

        Ok(())
    }

    fn generate_html_files(&self) -> Result<(), String> {
        for item in &self.pages {
            self.generate_content_page(item)?;
        }
        for item in &self.posts {
            self.generate_content_page(item)?;
        }
        Ok(())
    }

    fn generate_content_page(&self, item: &ContentItem) -> Result<(), String> {
        let page_path = self.output_folder.join(format!("{}.html", item.slug));
        let html = self.render_content(item)?;
        fs::write(page_path, html)
            .map_err(|e| format!("Failed to write content page: {}", e))?;
        Ok(())
    }

    fn generate_index_page(&self) -> Result<(), String> {
        let mut posts = self.posts.clone();
        posts.sort_by(|a, b| {
            let a_date = a.date.as_ref().map(|d| d.as_str()).unwrap_or("");
            let b_date = b.date.as_ref().map(|d| d.as_str()).unwrap_or("");
            b_date.cmp(a_date)
        });

        let html = self.render_index(&posts)?;
        fs::write(self.output_folder.join("index.html"), html)
            .map_err(|e| format!("Failed to write index: {}", e))?;
        Ok(())
    }

